import json,re
j=json.load(open('[REDACTED LOCAL PATH]'))
def walk(o):
    if isinstance(o,dict):
        if o.get('name')=='reference_genome':
            opts=o.get('options',[])
            print('count',len(opts))
            for label,val,sel in opts:
                if any(s in label.lower() for s in ['hg','grch','t2t','chm13','human','hs']):
                    print(repr(label), repr(val), sel)
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(j)
